function build_innerLoop()
% Reproducible R2024b interface-only model. No aircraft/vessel plant implied.
folder=fileparts(mfilename('fullpath')); name='innerLoop';
if bdIsLoaded(name), close_system(name,0); end
new_system(name);
set_param(name,'SolverType','Fixed-step','Solver','FixedStepDiscrete', ...
    'FixedStep','0.01','StopTime','0','SaveOutput','on', ...
    'OutputSaveName','yout','SaveFormat','Dataset','ReturnWorkspaceOutputs','on');
inputs={'timestamp',1;'helicopter_state',12;'ship_state',12; ...
    'T_body_camera','[4 4]';'H_ship_body',3;'gear_body',3; ...
    'nav_T_deck_camera','[4 4]';'nav_velocity_deck',3; ...
    'nav_covariance','[6 6]';'nav_healthy',1;'nav_timestamp',1; ...
    'nav_R_ned_deck','[3 3]'};
outputs={'T_world_deck','T_deck_camera','velocity_deck', ...
    'helicopter_velocity_ned_mps','ship_velocity_ned_mps', ...
    'gear_relative_truth_ned','gear_relative_estimate_ned', ...
    'relative_distance_estimate_m','relative_covariance_ned','feedback_valid', ...
    'navigation_velocity_camera_ned_mps','state_timestamp'};
add_block('simulink/User-Defined Functions/MATLAB Function', ...
    [name '/Frame_Unit_ReferencePoint_Conversion'],'Position',[370 70 700 720]);
rt=sfroot;
chart=rt.find('-isa','Stateflow.EMChart','Path',[name '/Frame_Unit_ReferencePoint_Conversion']);
chart.Script=fileread(fullfile(folder,'innerLoop_conversion.m'));
for k=1:size(inputs,1)
    dims=inputs{k,2}; if isnumeric(dims), dims=num2str(dims); end
    add_block('simulink/Sources/In1',[name '/' inputs{k,1}], ...
        'Port',num2str(k),'PortDimensions',dims,'OutDataTypeStr','double', ...
        'Position',[40 45+k*52 70 59+k*52]);
    add_line(name,[inputs{k,1} '/1'],['Frame_Unit_ReferencePoint_Conversion/' num2str(k)],'autorouting','on');
end
for k=1:numel(outputs)
    add_block('simulink/Sinks/Out1',[name '/' outputs{k}], ...
        'Port',num2str(k),'Position',[970 45+k*52 1000 59+k*52]);
    add_line(name,['Frame_Unit_ReferencePoint_Conversion/' num2str(k)],[outputs{k} '/1'],'autorouting','on');
end
Simulink.Annotation(name,['INTERFACE ONLY - no dynamics or controller. ' ...
    'External host enforces read -> sensors -> estimate -> feedback -> advance. ' ...
    'State: [NED CG metres; velocity knots; Euler radians; body omega rad/s]. ' ...
    'Helicopter velocity is BODY; ship velocity is NED. ' ...
    'Feedback = helicopter gear-plane centre MINUS H centre, NED metres. ' ...
    'Geometry offsets must be supplied from calibrated UH-60/ship configuration.']);
set_param(name,'SimulationCommand','update');
save_system(name,fullfile(folder,[name '.slx']));
close_system(name,0);
end
